<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useLiveChatStore } from '@/stores/live-chat';
const props=defineProps({active:{type:Boolean,default:true}});
const chat=useLiveChatStore();
const list=ref(null),composer=ref(null),input=ref(''),atBottom=ref(true),newMessages=ref(0);
let readTimer,savedScroll=0;
const canSend=computed(()=>props.active && chat.owner && chat.connection==='connected' && (!chat.staff || chat.canReply) && (!chat.staff || (chat.selected && chat.selected.status!=='closed' && chat.selected.customer.active && (!chat.selected.assignedAdminId || chat.selected.assignedAdminId===chat.owner || chat.canManage))));
const pending=computed(()=>chat.pending.filter(p=>p.conversationId===chat.selected?._id || (!p.conversationId && !chat.staff)));
const time=value=>new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
function receipt(message){
  if(chat.staff && message.senderKind==='support')return chat.selected?.reads?.some(r=>r.kind==='customer' && r.seq>=message.seq)?'Khách hàng đã xem':'Đã gửi';
  if(!chat.staff && message.senderKind==='customer'){const readers=chat.selected?.reads?.filter(r=>r.kind==='support' && r.seq>=message.seq) || [];return readers.length?'Đã xem bởi '+readers.slice(0,2).map(r=>r.name).join(', '):'Đã gửi';}
  return '';
}
function visible(){return props.active && !document.querySelector('dialog[open]') && document.visibilityState==='visible' && document.hasFocus() && atBottom.value && !chat.loading && !chat.loadingOlder;}
function seen(){clearTimeout(readTimer);if(!visible())return;const seq=chat.messages.at(-1)?.seq;if(seq)readTimer=setTimeout(()=>{if(visible())chat.markRead(seq);},150);}
function scroll(){if(!props.active || !list.value)return;savedScroll=list.value.scrollTop;atBottom.value=list.value.scrollHeight-list.value.scrollTop-list.value.clientHeight<56;if(atBottom.value)newMessages.value=0;seen();}
async function bottom(){await nextTick();if(props.active && list.value)list.value.scrollTop=list.value.scrollHeight;atBottom.value=true;newMessages.value=0;seen();}
async function older(){const node=list.value;if(!node)return;const height=node.scrollHeight,top=node.scrollTop;await chat.older();await nextTick();if(list.value===node){node.scrollTop=top+node.scrollHeight-height;scroll();}}
async function submit(){const text=input.value.trim();if(!text || text.length>2000 || !canSend.value)return;input.value='';chat.typingState(false);await chat.send(text);if(atBottom.value)await bottom();if(props.active)composer.value?.focus({preventScroll:true});}
function keydown(event){if(event.key==='Enter' && !event.shiftKey && !event.isComposing && event.keyCode!==229){event.preventDefault();void submit();}}
watch([()=>chat.selected?._id,()=>chat.owner],([id,owner],[oldId,oldOwner])=>{if(owner!==oldOwner || (oldId && id!==oldId))input.value='';if(id===oldId && owner===oldOwner)return;atBottom.value=true;newMessages.value=0;void bottom();});
watch(()=>chat.messages.at(-1)?.seq,async(value,previous)=>{if(value===previous)return;if(props.active && atBottom.value)await bottom();else newMessages.value++;});
watch(()=>props.active,async active=>{clearTimeout(readTimer);if(!active){chat.typingState(false);return;}await nextTick();if(atBottom.value)await bottom();else if(list.value){list.value.scrollTop=savedScroll;seen();}},{flush:'sync'});
watch(()=>chat.loading,async value=>{if(!value && atBottom.value)await bottom();});
watch(()=>pending.value.length,()=>{if(atBottom.value)void bottom();});
onMounted(()=>{window.addEventListener('focus',seen);document.addEventListener('visibilitychange',seen);void bottom();});
onBeforeUnmount(()=>{clearTimeout(readTimer);chat.typingState(false);window.removeEventListener('focus',seen);document.removeEventListener('visibilitychange',seen);});
defineExpose({focus:()=>composer.value?.focus({preventScroll:true})});
</script>
<template><div class="lc-thread"><div v-if="chat.error" class="lc-error" role="alert">{{ chat.error }}<button type="button" @click="chat.reconnect">Tải lại</button></div><div v-if="chat.selected?.status==='closed'" class="lc-context">Hội thoại đã kết thúc. {{ chat.staff?'Mở lại để tiếp tục trả lời.':'Gửi tin nhắn mới để mở lại và tiếp tục hỗ trợ.' }}</div><div ref="list" class="lc-message-list" role="log" :aria-live="chat.loadingOlder?'off':'polite'" aria-label="Lịch sử chat hỗ trợ" :aria-busy="chat.loading" tabindex="0" @scroll.passive="scroll"><p v-if="chat.loading" class="lc-empty" role="status">Đang tải lịch sử…</p><button v-if="chat.hasOlder" type="button" class="lc-load-older" :disabled="chat.loadingOlder" @click="older">{{ chat.loadingOlder?'Đang tải…':'Tải tin cũ hơn' }}</button><div v-if="!chat.loading && !chat.messages.length" class="lc-empty"><span class="lc-empty-icon" aria-hidden="true"><i class="fa-regular fa-comments"></i></span><strong>Bạn cần hỗ trợ điều gì?</strong><p>Tin nhắn đầu tiên sẽ bắt đầu cuộc trò chuyện với bộ phận hỗ trợ Fresh Mart.</p></div><article v-for="message in chat.messages" :key="message._id" class="lc-message" :class="{'lc-message--mine':message.senderId===chat.owner}" :data-seq="message.seq"><small class="lc-sender">{{ message.senderName }}{{ message.senderKind==='support'?' · Hỗ trợ':'' }}</small><p class="lc-bubble">{{ message.content }}</p><div class="lc-message-meta"><time :datetime="message.createdAt">{{ time(message.createdAt) }}</time><small v-if="receipt(message)">{{ receipt(message) }}</small></div></article><article v-for="item in pending" :key="item.clientMessageId" class="lc-message lc-message--mine lc-pending"><p class="lc-bubble">{{ item.content }}</p><small v-if="item.status==='sending'" role="status">Đang gửi…</small><div v-else class="lc-failed"><span>Chưa gửi được</span><button type="button" :disabled="chat.connection!=='connected'" @click="chat.send(item.content,item)">Thử lại tin nhắn</button></div></article></div><button v-if="newMessages" type="button" class="lc-new-messages" @click="bottom">{{ newMessages }} tin nhắn mới ↓</button><div class="lc-typing" role="status"><span v-if="chat.typing.length">{{ chat.typing.map(t=>t.name).join(', ') }} đang nhập…</span></div><form class="lc-composer" @submit.prevent="submit"><label class="lc-visually-hidden" :for="chat.staff?'staff-chat-input':'customer-chat-input'">Nội dung tin nhắn</label><textarea :id="chat.staff?'staff-chat-input':'customer-chat-input'" ref="composer" v-model="input" maxlength="2000" rows="2" :disabled="!canSend" placeholder="Nhập tin nhắn…" @keydown="keydown" @input="chat.typingState(!!input.trim())"></textarea><div class="lc-composer-bottom"><small>{{ chat.connection!=='connected'?'Đang mất kết nối':!canSend?'Chưa thể trả lời hội thoại này':'Enter để gửi · Shift + Enter xuống dòng' }}</small><button type="submit" class="lc-primary" :disabled="!canSend || !input.trim()"><i class="fa-solid fa-paper-plane" aria-hidden="true"></i><span>Gửi</span></button></div></form></div></template>
